/// Part 1: reads the stock of one warehouse and reports what is below the line it was asked to keep, which is a long comment on purpose, so that it wraps inside the box and takes a second line.
fn stock_1(warehouse: &Warehouse, floor: u32) -> Vec<Item> {
    let mut low = Vec::new();
    for item in warehouse.items() {
        if item.count < floor {
            low.push(item.clone());
        }
    }

	// a tab here, as an editor with tabs would write the line
	low.sort_by_key(|item| item.count);
    low
}

